:setvar TargetDatabase "NCRMS"
USE [$(TargetDatabase)];
GO
SET NOCOUNT ON;
GO
CREATE TABLE #ExpectedTables ([SchemaName] sysname COLLATE DATABASE_DEFAULT NOT NULL, [ObjectName] sysname COLLATE DATABASE_DEFAULT NOT NULL, [ExpectedHash] varchar(64) COLLATE DATABASE_DEFAULT NOT NULL, PRIMARY KEY ([SchemaName], [ObjectName]));
CREATE TABLE #ExpectedModules ([SchemaName] sysname COLLATE DATABASE_DEFAULT NOT NULL, [ObjectName] sysname COLLATE DATABASE_DEFAULT NOT NULL, [ObjectType] char(2) COLLATE DATABASE_DEFAULT NOT NULL, [ExpectedHash] varchar(64) COLLATE DATABASE_DEFAULT NOT NULL, PRIMARY KEY ([SchemaName], [ObjectName], [ObjectType]));
GO
SELECT tables.object_id AS ObjectId, schemas.name COLLATE DATABASE_DEFAULT AS SchemaName, tables.name COLLATE DATABASE_DEFAULT AS ObjectName,
    CONVERT(varchar(64), HASHBYTES('SHA2_256', CONVERT(varbinary(max), CONCAT(
        (SELECT columns.column_id, columns.name, typeSchemas.name AS TypeSchema, types.name AS TypeName, columns.max_length, columns.precision, columns.scale, columns.collation_name, columns.is_nullable, columns.is_identity, identityColumns.seed_value, identityColumns.increment_value, columns.is_computed, computedColumns.definition AS ComputedDefinition, computedColumns.is_persisted, defaultConstraints.definition AS DefaultDefinition, columns.is_rowguidcol, columns.generated_always_type
         FROM sys.columns AS columns INNER JOIN sys.types AS types ON types.user_type_id = columns.user_type_id INNER JOIN sys.schemas AS typeSchemas ON typeSchemas.schema_id = types.schema_id LEFT JOIN sys.identity_columns AS identityColumns ON identityColumns.object_id = columns.object_id AND identityColumns.column_id = columns.column_id LEFT JOIN sys.computed_columns AS computedColumns ON computedColumns.object_id = columns.object_id AND computedColumns.column_id = columns.column_id LEFT JOIN sys.default_constraints AS defaultConstraints ON defaultConstraints.object_id = columns.default_object_id WHERE columns.object_id = tables.object_id ORDER BY columns.column_id FOR JSON PATH, INCLUDE_NULL_VALUES),
        N'|INDEXES|',
        (SELECT indexes.name, indexes.type, indexes.is_unique, indexes.is_primary_key, indexes.is_unique_constraint, indexes.has_filter, indexes.filter_definition, indexes.is_disabled, indexes.fill_factor, JSON_QUERY((SELECT indexColumns.index_column_id, indexColumns.key_ordinal, indexColumns.is_descending_key, indexColumns.is_included_column, columns.name AS ColumnName FROM sys.index_columns AS indexColumns INNER JOIN sys.columns AS columns ON columns.object_id = indexColumns.object_id AND columns.column_id = indexColumns.column_id WHERE indexColumns.object_id = indexes.object_id AND indexColumns.index_id = indexes.index_id ORDER BY indexColumns.index_column_id FOR JSON PATH, INCLUDE_NULL_VALUES)) AS Columns FROM sys.indexes AS indexes WHERE indexes.object_id = tables.object_id AND indexes.index_id > 0 AND indexes.is_hypothetical = 0 ORDER BY indexes.name FOR JSON PATH, INCLUDE_NULL_VALUES),
        N'|FOREIGN_KEYS|',
        (SELECT foreignKeys.name, referencedSchemas.name AS ReferencedSchema, referencedTables.name AS ReferencedTable, foreignKeys.delete_referential_action, foreignKeys.update_referential_action, foreignKeys.is_not_trusted, foreignKeys.is_disabled, JSON_QUERY((SELECT foreignKeyColumns.constraint_column_id, parentColumns.name AS ParentColumn, referencedColumns.name AS ReferencedColumn FROM sys.foreign_key_columns AS foreignKeyColumns INNER JOIN sys.columns AS parentColumns ON parentColumns.object_id = foreignKeyColumns.parent_object_id AND parentColumns.column_id = foreignKeyColumns.parent_column_id INNER JOIN sys.columns AS referencedColumns ON referencedColumns.object_id = foreignKeyColumns.referenced_object_id AND referencedColumns.column_id = foreignKeyColumns.referenced_column_id WHERE foreignKeyColumns.constraint_object_id = foreignKeys.object_id ORDER BY foreignKeyColumns.constraint_column_id FOR JSON PATH, INCLUDE_NULL_VALUES)) AS Columns FROM sys.foreign_keys AS foreignKeys INNER JOIN sys.tables AS referencedTables ON referencedTables.object_id = foreignKeys.referenced_object_id INNER JOIN sys.schemas AS referencedSchemas ON referencedSchemas.schema_id = referencedTables.schema_id WHERE foreignKeys.parent_object_id = tables.object_id ORDER BY foreignKeys.name FOR JSON PATH, INCLUDE_NULL_VALUES),
        N'|CHECKS|',
        (SELECT checkConstraints.name, checkConstraints.definition, checkConstraints.is_not_trusted, checkConstraints.is_disabled, checkConstraints.uses_database_collation FROM sys.check_constraints AS checkConstraints WHERE checkConstraints.parent_object_id = tables.object_id ORDER BY checkConstraints.name FOR JSON PATH, INCLUDE_NULL_VALUES),
        N'|TRIGGERS|',
        (SELECT triggers.name, triggers.is_disabled, sqlModules.definition FROM sys.triggers AS triggers INNER JOIN sys.sql_modules AS sqlModules ON sqlModules.object_id = triggers.object_id WHERE triggers.parent_id = tables.object_id ORDER BY triggers.name FOR JSON PATH, INCLUDE_NULL_VALUES),
        N'|EXTENDED_PROPERTIES|',
        (SELECT extendedProperties.class, extendedProperties.major_id, extendedProperties.minor_id, extendedProperties.name, CONVERT(nvarchar(max), extendedProperties.value) AS Value FROM sys.extended_properties AS extendedProperties WHERE extendedProperties.class = 1 AND extendedProperties.major_id = tables.object_id ORDER BY extendedProperties.minor_id, extendedProperties.name FOR JSON PATH, INCLUDE_NULL_VALUES)
    ))), 2) COLLATE DATABASE_DEFAULT AS ActualHash
INTO #ActualTableHashes
FROM sys.tables AS tables INNER JOIN sys.schemas AS schemas ON schemas.schema_id = tables.schema_id WHERE tables.is_ms_shipped = 0;
GO
SELECT N'TABLE_MISSING' AS Issue, expected.SchemaName, expected.ObjectName, expected.ExpectedHash, CAST(NULL AS varchar(64)) AS ActualHash FROM #ExpectedTables AS expected LEFT JOIN #ActualTableHashes AS actual ON actual.SchemaName = expected.SchemaName AND actual.ObjectName = expected.ObjectName WHERE actual.ObjectName IS NULL
UNION ALL SELECT N'TABLE_SCHEMA_MISMATCH', expected.SchemaName, expected.ObjectName, expected.ExpectedHash, actual.ActualHash FROM #ExpectedTables AS expected INNER JOIN #ActualTableHashes AS actual ON actual.SchemaName = expected.SchemaName AND actual.ObjectName = expected.ObjectName WHERE expected.ExpectedHash <> actual.ActualHash;
GO
SELECT schemas.name COLLATE DATABASE_DEFAULT AS SchemaName, objects.name COLLATE DATABASE_DEFAULT AS ObjectName, objects.type COLLATE DATABASE_DEFAULT AS ObjectType, CONVERT(nvarchar(max), modules.definition) AS NormalizedDefinition INTO #ActualModuleDefinitions FROM sys.objects AS objects INNER JOIN sys.schemas AS schemas ON schemas.schema_id = objects.schema_id INNER JOIN sys.sql_modules AS modules ON modules.object_id = objects.object_id WHERE objects.is_ms_shipped = 0 AND objects.type IN ('P', 'V', 'FN', 'IF', 'TF');
UPDATE #ActualModuleDefinitions SET NormalizedDefinition = REPLACE(REPLACE(REPLACE(NormalizedDefinition, NCHAR(13) + NCHAR(10), NCHAR(10)), NCHAR(13), NCHAR(10)), NCHAR(10), NCHAR(13) + NCHAR(10));
UPDATE #ActualModuleDefinitions SET NormalizedDefinition = NCHAR(13) + NCHAR(10) + NormalizedDefinition;
WHILE EXISTS (SELECT 1 FROM #ActualModuleDefinitions WHERE NormalizedDefinition LIKE N'%' + NCHAR(13) + NCHAR(10) + N' ' + NCHAR(9) + N'%') UPDATE #ActualModuleDefinitions SET NormalizedDefinition = REPLACE(NormalizedDefinition, NCHAR(13) + NCHAR(10) + N' ' + NCHAR(9), NCHAR(13) + NCHAR(10) + NCHAR(9));
UPDATE #ActualModuleDefinitions SET NormalizedDefinition = SUBSTRING(NormalizedDefinition, 3, (DATALENGTH(NormalizedDefinition) / 2) - 2);
WHILE EXISTS (SELECT 1 FROM #ActualModuleDefinitions WHERE NormalizedDefinition LIKE N'% ' + NCHAR(13) + NCHAR(10) + N'%' OR NormalizedDefinition LIKE N'%' + NCHAR(9) + NCHAR(13) + NCHAR(10) + N'%') UPDATE #ActualModuleDefinitions SET NormalizedDefinition = REPLACE(REPLACE(NormalizedDefinition, N' ' + NCHAR(13) + NCHAR(10), NCHAR(13) + NCHAR(10)), NCHAR(9) + NCHAR(13) + NCHAR(10), NCHAR(13) + NCHAR(10));
WHILE EXISTS (SELECT 1 FROM #ActualModuleDefinitions WHERE RIGHT(NormalizedDefinition, 2) = NCHAR(13) + NCHAR(10)) UPDATE #ActualModuleDefinitions SET NormalizedDefinition = LEFT(NormalizedDefinition, (DATALENGTH(NormalizedDefinition) / 2) - 2) WHERE RIGHT(NormalizedDefinition, 2) = NCHAR(13) + NCHAR(10);
SELECT SchemaName, ObjectName, ObjectType, CONVERT(varchar(64), HASHBYTES('SHA2_256', CONVERT(varbinary(max), NormalizedDefinition)), 2) COLLATE DATABASE_DEFAULT AS ActualHash INTO #ActualModuleHashes FROM #ActualModuleDefinitions;
SELECT N'MODULE_MISSING' AS Issue, expected.SchemaName, expected.ObjectName, expected.ObjectType, expected.ExpectedHash, CAST(NULL AS varchar(64)) AS ActualHash FROM #ExpectedModules AS expected LEFT JOIN #ActualModuleHashes AS actual ON actual.SchemaName = expected.SchemaName AND actual.ObjectName = expected.ObjectName AND actual.ObjectType = expected.ObjectType WHERE actual.ObjectName IS NULL
UNION ALL SELECT N'MODULE_DEFINITION_MISMATCH', expected.SchemaName, expected.ObjectName, expected.ObjectType, expected.ExpectedHash, actual.ActualHash FROM #ExpectedModules AS expected INNER JOIN #ActualModuleHashes AS actual ON actual.SchemaName = expected.SchemaName AND actual.ObjectName = expected.ObjectName AND actual.ObjectType = expected.ObjectType WHERE expected.ExpectedHash <> actual.ActualHash
UNION ALL SELECT N'MODULE_EXTRA', actual.SchemaName, actual.ObjectName, actual.ObjectType, CAST(NULL AS varchar(64)), actual.ActualHash FROM #ActualModuleHashes AS actual LEFT JOIN #ExpectedModules AS expected ON expected.SchemaName = actual.SchemaName AND expected.ObjectName = actual.ObjectName AND expected.ObjectType = actual.ObjectType WHERE expected.ObjectName IS NULL;
GO
DECLARE @IssueCount int = 0;
SELECT @IssueCount += COUNT(*) FROM #ExpectedTables AS expected LEFT JOIN #ActualTableHashes AS actual ON actual.SchemaName = expected.SchemaName AND actual.ObjectName = expected.ObjectName WHERE actual.ObjectName IS NULL OR expected.ExpectedHash <> actual.ActualHash;
SELECT @IssueCount += COUNT(*) FROM #ExpectedModules AS expected FULL JOIN #ActualModuleHashes AS actual ON actual.SchemaName = expected.SchemaName AND actual.ObjectName = expected.ObjectName AND actual.ObjectType = expected.ObjectType WHERE expected.ObjectName IS NULL OR actual.ObjectName IS NULL OR expected.ExpectedHash <> actual.ActualHash;
IF @IssueCount > 0 THROW 51010, 'Schema validation failed. Review the result sets above.', 1;
PRINT N'Schema validation passed for all EF-managed tables and all known modules.';
GO
